<section class="store-section wardrobe-section <?=$sectionClass?>" id="<?=store_h($key)?>" style="<?=$sectionStyle?>"><div class="builder-section-inner"><div class="section-heading <?=$sectionAlign==='center'?'center':''?>"><div><?php if($showSectionEyebrow&&$eyebrow!==''):?><span><?=store_h($eyebrow)?></span><?php endif;?><?php if($showSectionHeading):?><h2><?=store_h($title?:'Shop the Collections')?></h2><?php endif;?><?php if($showSectionSubtitle&&trim($subtitle)!==''):?><p><?=store_h($subtitle)?></p><?php endif;?></div><?php if($showSectionViewAll&&$viewLabel!==''):?><a href="<?=store_h($viewUrl)?>"><?=store_h($viewLabel)?> →</a><?php endif;?></div><div class="wardrobe-grid builder-grid"><?php foreach(array_slice($items,0,$maxItems) as $item):$ic=$itemSettings($item);$pos=$focalCss($ic);$mobilePos=$focalCss($ic,'mobile_',$pos);?><a class="wardrobe-card" style="<?=$imageStyle($item['image_path']??null,$pos,$mobilePos)?>" href="<?=store_h($link($item,store_catalog_url()))?>"><div><strong><?=store_h($item['title']??'Collection')?></strong><small><?=store_h($item['subtitle']??'')?></small></div></a><?php endforeach;?></div></div></section>

<?php elseif($type==='gift_banner'):
  if(!$first)return;
  $ic=$itemSettings($first);$literalCopy=!empty($ic['literal_copy']);$giftImage=store_image_path($first['image_path']??'');$giftMobileImage=store_image_path($first['mobile_image_path']??'');$giftBase=$giftImage!==''?$giftImage:$giftMobileImage;$giftDelivery=$giftBase!==''?store_image_variant_path($giftBase,'lg'):'';$giftMobileSource=$giftMobileImage!==''?$giftMobileImage:$giftBase;$giftMobileDelivery=$giftMobileSource!==''?store_image_variant_path($giftMobileSource,'md'):'';$pos=$focalCss($ic);$mobilePos=$focalCss($ic,'mobile_',$pos);$overlay=max(0,min(80,(int)($ic['overlay']??45)))/100;$campaignD=max(360,min(900,(int)($ic['desktop_height']??560)));$campaignM=max(360,min(900,(int)($ic['mobile_height']??560)));$textAlign=(string)($ic['text_align']??'left');$textVertical=(string)($ic['text_vertical']??'middle');$textColour=(string)($ic['text_color']??'#ffffff');$buttonStyle=(string)($ic['button_style']??'gold');$secondLabel=(string)($ic['second_cta_label']??'');$secondUrl=(string)($ic['second_cta_url']??'');
?>
<section class="gift-banner builder-campaign builder-text-<?=store_h($textAlign)?> builder-vertical-<?=store_h($textVertical)?><?=$giftBase===''?' no-media':''?>" id="<?=store_h($key)?>" style="--campaign-height:<?=$campaignD?>px;--campaign-height-mobile:<?=$campaignM?>px;--campaign-overlay:<?=$overlay?>;--campaign-position:<?=store_h($pos)?>;--campaign-mobile-position:<?=store_h($mobilePos)?>;--campaign-text:<?=store_h($textColour)?>;<?php if($giftBase!==''):?>--gift-image:url('<?=store_h(url($giftDelivery))?>');<?php endif;?><?php if($giftMobileDelivery!==''):?>--gift-mobile-image:url('<?=store_h(url($giftMobileDelivery))?>');<?php endif;?>"><div><?php $giftEyebrow=trim((string)($first['eyebrow']??''));$giftTitle=trim((string)($first['title']??''));$giftSubtitle=trim((string)($first['subtitle']??''));if(!$literalCopy){if($giftEyebrow==='')$giftEyebrow='GIFTING';if($giftTitle==='')$giftTitle=trim($title!==''?$title:'Gifts');if($giftSubtitle==='')$giftSubtitle=trim($subtitle);}if($giftEyebrow!==''):?><span><?=store_h($giftEyebrow)?></span><?php endif;?><?php if($giftTitle!==''):?><h2><?=store_h($giftTitle)?></h2><?php endif;?><?php if($giftSubtitle!==''):?><p><?=store_h($giftSubtitle)?></p><?php endif;?><div class="hero-actions"><?php if(!empty($first['cta_label'])):?><a class="store-btn <?=store_h($buttonStyle)?>" href="<?=store_h($link($first,store_catalog_url()))?>"><?=store_h($first['cta_label'])?> →</a><?php endif;?><?php if($secondLabel!==''&&$secondUrl!==''):?><a class="store-btn light" href="<?=store_h($secondUrl)?>"><?=store_h($secondLabel)?> →</a><?php endif;?></div></div></section>

<?php elseif($type==='brand_grid'):
  $brandRows=[];if($items){foreach($items as $item){
// Only explicitly uploaded brand art. Do not substitute third-party demo logos.
$brandImage='';
foreach(['brand_logo_path','brand_cover_path','image_path'] as $imageField){
 $candidate=store_image_path($item[$imageField]??'');
 if($candidate!==''&&!str_contains($candidate,'/curated/')&&!str_contains($candidate,'commons.wikimedia.org/wiki/Special:FilePath/')){$brandImage=$candidate;break;}
}
$brandDisplayImage=$brandImage!==''?url(store_image_variant_path($brandImage,'sm')):'';
$brandRows[]=['name'=>$item['title']??$item['brand_name']??'Brand','url'=>$link($item,store_catalog_url(['brand'=>(string)($item['brand_slug']??'')])),'image'=>$brandDisplayImage];}}if(!$brandRows)return;if($viewUrl==='')$viewUrl=store_catalog_url();
?>
