<?php elseif($type==='custom'):
  if($viewUrl==='')$viewUrl='#';
?>
<section class="store-section custom-section <?=$sectionClass?>" id="<?=store_h($key)?>" style="<?=$sectionStyle?>"><div class="builder-section-inner"><div class="section-heading <?=$sectionAlign==='center'?'center':''?>"><div><?php if($showSectionEyebrow&&$eyebrow!==''):?><span><?=store_h($eyebrow)?></span><?php endif;?><?php if($showSectionHeading):?><h2><?=store_h($title?:'Discover More')?></h2><?php endif;?><?php if($showSectionSubtitle&&trim($subtitle)!==''):?><p><?=store_h($subtitle)?></p><?php endif;?></div><?php if($showSectionViewAll&&$viewLabel!==''&&$viewUrl!=='#'):?><a href="<?=store_h($viewUrl)?>"><?=store_h($viewLabel)?> →</a><?php endif;?></div><?php if($items):?><div class="category-grid builder-grid"><?php foreach(array_slice($items,0,$maxItems) as $item):$ic=$itemSettings($item);$cardAction=($ic['show_action']??true)!==false;$cardActionLabel=trim((string)($item['cta_label']??''))?:'DISCOVER';$pos=$focalCss($ic);$mobilePos=$focalCss($ic,'mobile_',$pos);?><a class="category-card" href="<?=store_h($link($item,'#'))?>" style="<?=$imageStyle($item['image_path']??null,$pos,$mobilePos)?>"><div class="category-card-content"><strong><?=store_h($item['title']??'')?></strong><small><?=store_h($item['subtitle']??'')?></small><?php if($cardAction):?><span><?=store_h($cardActionLabel)?> →</span><?php endif;?></div></a><?php endforeach;?></div><?php endif;?></div></section>
<?php endif;?>
